!         TO 1
!
IX = 1
IY = 1
IF(INCX.LT.0)IX = (-N+1)*INCX + 1
IF(INCY.LT.0)IY = (-N+1)*INCY + 1
DO I = 1,N
  CTEMP = CX(IX)
  CX(IX) = CY(IY)
  CY(IY) = CTEMP
