END SUBROUTINE CSWAP

SUBROUTINE  SROT (N,SX,INCX,SY,INCY,C,S)
IMPLICIT NONE
!
!     APPLIES A PLANE ROTATION.
!     JACK DONGARRA, LINPACK, 3/11/78.
!
REAL, INTENT(INOUT) :: SX(*), SY(*)
REAL :: STEMP
REAL, INTENT(IN) :: C, S
INTEGER :: I
INTEGER, INTENT(IN) :: INCX, INCY
INTEGER :: IX, IY
INTEGER, INTENT(IN) :: N
!
IF(N.LE.0)RETURN
IF(INCX.EQ.1.AND.INCY.EQ.1)GO TO 20
!
!       CODE FOR UNEQUAL INCREMENTS OR EQUAL INCREMENTS NOT EQUAL
!         TO 1
!
IX = 1
IY = 1
IF(INCX.LT.0)IX = (-N+1)*INCX + 1
IF(INCY.LT.0)IY = (-N+1)*INCY + 1
DO I = 1,N
  STEMP = C*SX(IX) + S*SY(IY)
  SY(IY) = C*SY(IY) - S*SX(IX)
  SX(IX) = STEMP
  IX = IX + INCX
  IY = IY + INCY
END DO
RETURN
!
!       CODE FOR BOTH INCREMENTS EQUAL TO 1
!
20 DO I = 1,N
  STEMP = C*SX(I) + S*SY(I)
  SY(I) = C*SY(I) - S*SX(I)
  SX(I) = STEMP
END DO
RETURN
END SUBROUTINE SROT

SUBROUTINE  DROT (N,DX,INCX,DY,INCY,C,S)
IMPLICIT NONE
!
!     APPLIES A PLANE ROTATION.
!     JACK DONGARRA, LINPACK, 3/11/78.
!
DOUBLE PRECISION, INTENT(INOUT) :: DX(*), DY(*)
DOUBLE PRECISION :: DTEMP
DOUBLE PRECISION, INTENT(IN) :: C, S
INTEGER :: I
INTEGER, INTENT(IN) :: INCX, INCY
INTEGER :: IX, IY
INTEGER, INTENT(IN) :: N
!
IF(N.LE.0)RETURN
IF(INCX.EQ.1.AND.INCY.EQ.1)GO TO 20
!
!       CODE FOR UNEQUAL INCREMENTS OR EQUAL INCREMENTS NOT EQUAL
!         TO 1
!
IX = 1
IY = 1
IF(INCX.LT.0)IX = (-N+1)*INCX + 1
IF(INCY.LT.0)IY = (-N+1)*INCY + 1
DO I = 1,N
  DTEMP = C*DX(IX) + S*DY(IY)
  DY(IY) = C*DY(IY) - S*DX(IX)
  DX(IX) = DTEMP
  IX = IX + INCX
  IY = IY + INCY
END DO
RETURN
!
!       CODE FOR BOTH INCREMENTS EQUAL TO 1
!
20 DO I = 1,N
  DTEMP = C*DX(I) + S*DY(I)
  DY(I) = C*DY(I) - S*DX(I)
  DX(I) = DTEMP
END DO
RETURN
END SUBROUTINE DROT

SUBROUTINE  CSROT (N,CX,INCX,CY,INCY,C,S)
IMPLICIT NONE
!
!     APPLIES A PLANE ROTATION, WHERE THE COS AND SIN (C AND S) ARE REAL
!     AND THE VECTORS CX AND CY ARE COMPLEX.
!     JACK DONGARRA, LINPACK, 3/11/78.
!
COMPLEX, INTENT(INOUT) :: CX(*), CY(*)
COMPLEX :: CTEMP
REAL, INTENT(IN) :: C, S
INTEGER :: I
INTEGER, INTENT(IN) :: INCX, INCY
INTEGER :: IX, IY
INTEGER, INTENT(IN) :: N
!
IF(N.LE.0)RETURN
IF(INCX.EQ.1.AND.INCY.EQ.1)GO TO 20
!
!       CODE FOR UNEQUAL INCREMENTS OR EQUAL INCREMENTS NOT EQUAL
!         TO 1
!
IX = 1
IY = 1
IF(INCX.LT.0)IX = (-N+1)*INCX + 1
IF(INCY.LT.0)IY = (-N+1)*INCY + 1
DO I = 1,N
  CTEMP = C*CX(IX) + S*CY(IY)
  CY(IY) = C*CY(IY) - S*CX(IX)
  CX(IX) = CTEMP
  IX = IX + INCX
  IY = IY + INCY
END DO
RETURN
!
!       CODE FOR BOTH INCREMENTS EQUAL TO 1
!
20 DO I = 1,N
  CTEMP = C*CX(I) + S*CY(I)
  CY(I) = C*CY(I) - S*CX(I)
  CX(I) = CTEMP
END DO
RETURN
END SUBROUTINE CSROT

SUBROUTINE SROTMG (SD1,SD2,SX1,SY1,SPARAM)
IMPLICIT NONE
REAL, INTENT(INOUT) :: SD1, SD2, SPARAM(5), SX1
REAL, INTENT(IN) :: SY1
REAL :: GAM, GAMSQ, ONE, RGAMSQ, SFLAG, SH11, SH12, SH21, SH22, &
&SP1, SP2, SQ1, SQ2, STEMP, SU, TWO, ZERO
!
!     CONSTRUCT THE MODIFIED GIVENS TRANSFORMATION MATRIX H WHICH ZEROS
!     THE SECOND COMPONENT OF THE 2-VECTOR  (SQRT(SD1)*SX1,SQRT(SD2)*
!     SY1)**T.
!     WITH SPARAM(1)=SFLAG, H HAS ONE OF THE FOLLOWING FORMS..
!
!     SFLAG=-1.E0     SFLAG=0.E0        SFLAG=1.E0     SFLAG=-2.E0
!
!       (SH11  SH12)    (1.E0  SH12)    (SH11  1.E0)    (1.E0  0.E0)
!     H=(          )    (          )    (          )    (          )
!       (SH21  SH22),   (SH21  1.E0),   (-1.E0 SH22),   (0.E0  1.E0).
!
!     LOCATIONS 2-4 OF SPARAM CONTAIN SH11,SH21,SH12, AND SH22
!     RESPECTIVELY. (VALUES OF 1.E0, -1.E0, OR 0.E0 IMPLIED BY THE
!     VALUE OF SPARAM(1) ARE NOT STORED IN SPARAM.)
!
!     IT IS ASSUMED THAT GAMSQ = GAM*GAM AND RGAMSQ = ONE/(GAM*GAM).
!     THE VALUES OF GAMSQ AND RGAMSQ SET IN THE DATA STATEMENT MAY BE
!     INEXACT.  THIS IS OK AS THEY ARE ONLY USED FOR TESTING THE SIZE
!     OF SD1 AND SD2.  ALL ACTUAL SCALING OF DATA IS DONE USING GAM.
!
!
DATA ZERO,ONE,TWO /0.E0,1.E0,2.E0/
DATA GAM,GAMSQ,RGAMSQ/4096.E0,1.67772E7,5.96046E-8/
!
IF (SD1 .LT. ZERO) GO TO 60
SP2 = SD2*SY1
IF (SP2 .NE. ZERO) GO TO 20
    SFLAG = -TWO
    GO TO 260
!
!     REGULAR-CASE..
!
20 SP1 = SD1*SX1
SQ1 = SP1*SX1
SQ2 = SP2*SY1
!
IF (ABS(SQ1) .LE. ABS(SQ2)) GO TO 40
    SH21 = -SY1/SX1
    SH12 = SP2/SP1
!
    SU = ONE - SH12*SH21
    IF (SU .LE. ZERO) GO TO 60
!
         SFLAG = ZERO
         SH11 = ONE
         SH22 = ONE
         SD1 = SD1/SU
         SD2 = SD2/SU
         SX1 = SX1*SU
!         GO SCALE-CHECK..
         GO TO 100
!
40 CONTINUE
    IF (SD2 .LT. ZERO) GO TO 60
         SFLAG = ONE
         SH11 = SP1/SP2
         SH21 = -ONE
         SH12 = ONE
         SH22 = SX1/SY1
!
         SU = ONE + SH11*SH22
         STEMP = SD2/SU
         SD2 = SD1/SU
         SD1 = STEMP
         SX1 = SY1*SU
!         GO SCALE-CHECK
         GO TO 100
!
!     PROCEDURE..ZERO-H-D-AND-SX1..
!
60 CONTINUE
    SFLAG = -ONE
    SH11 = ZERO
    SH12 = ZERO
    SH21 = ZERO
    SH22 = ZERO
!
    SD1 = ZERO
    SD2 = ZERO
    SX1 = ZERO
    GO TO 250
!
!     PROCEDURE..SCALE-CHECK
!
100 CONTINUE
110 CONTINUE
    IF (SD1 .GT. RGAMSQ) GO TO 130
         IF (SD1 .EQ. ZERO) GO TO 160
         SFLAG = -ONE
         SD1 = SD1*(GAM*GAM)
         SX1 = SX1/GAM
         SH11 = SH11/GAM
         SH12 = SH12/GAM
    GO TO 110
!
130 CONTINUE
140 CONTINUE
    IF (SD1 .LT. GAMSQ) GO TO 160
         SFLAG = -ONE
         SD1 = SD1/(GAM*GAM)
         SX1 = SX1*GAM
         SH11 = SH11*GAM
         SH12 = SH12*GAM
    GO TO 140
!
160 CONTINUE
170 CONTINUE
    IF (ABS(SD2) .GT. RGAMSQ) GO TO 190
         IF (SD2 .EQ. ZERO) GO TO 220
         SFLAG = -ONE
         SD2 = SD2*(GAM*GAM)
         SH21 = SH21/GAM
         SH22 = SH22/GAM
    GO TO 170
!
190 CONTINUE
200 CONTINUE
    IF (ABS(SD2) .LT. GAMSQ) GO TO 220
         SFLAG = -ONE
         SD2 = SD2/(GAM*GAM)
         SH21 = SH21*GAM
         SH22 = SH22*GAM
    GO TO 200
!
220 CONTINUE
    IF(SFLAG)250,230,240
230 CONTINUE
         SPARAM(3)=SH21
         SPARAM(4)=SH12
         GO TO 260
240 CONTINUE
         SPARAM(2)=SH11
         SPARAM(5)=SH22
         GO TO 260
250 CONTINUE
         SPARAM(2)=SH11
         SPARAM(3)=SH21
         SPARAM(4)=SH12
         SPARAM(5)=SH22
260 CONTINUE
    SPARAM(1)=SFLAG
    RETURN
END SUBROUTINE SROTMG

SUBROUTINE SROTM (N,SX,INCX,SY,INCY,SPARAM)
IMPLICIT NONE
INTEGER, INTENT(IN) :: INCX, INCY, N
REAL :: SPARAM(5)
REAL, INTENT(INOUT) :: SX(*), SY(*)
INTEGER :: I, KX, KY, NSTEPS
REAL :: SFLAG, SH11, SH12, SH21, SH22, TWO, W, Z, ZERO
!
!     APPLY THE MODIFIED GIVENS TRANSFORMATION, H, TO THE 2 BY N MATRIX
!
!     (SX**T), WHERE **T INDICATES TRANSPOSE. THE ELEMENTS OF SX ARE IN
!     (SY**T)
!
!     SX(LX+I*INCX), I = 0 TO N-1, WHERE LX = 1 IF INCX .GE. 0, ELSE
!     LX = (-INCX)*N, AND SIMILARLY FOR SY USING USING LY AND INCY.
!
!     WITH SPARAM(1)=SFLAG, H HAS ONE OF THE FOLLOWING FORMS..
!
!     SFLAG=-1.E0     SFLAG=0.E0        SFLAG=1.E0     SFLAG=-2.E0
!
!       (SH11  SH12)    (1.E0  SH12)    (SH11  1.E0)    (1.E0  0.E0)
!     H=(          )    (          )    (          )    (          )
!       (SH21  SH22),   (SH21  1.E0),   (-1.E0 SH22),   (0.E0  1.E0).
!
!
DATA ZERO,TWO/0.E0,2.E0/
!
SFLAG=SPARAM(1)
IF(N .LE. 0 .OR.(SFLAG+TWO.EQ.ZERO)) GO TO 140
    IF(.NOT.(INCX.EQ.INCY.AND. INCX .GT.0)) GO TO 70
!
         NSTEPS=N*INCX
         IF(SFLAG) 50,10,30
10 CONTINUE
         SH21=SPARAM(3)
         SH12=SPARAM(4)
              DO I=1,NSTEPS,INCX
              W=SX(I)
              Z=SY(I)
              SX(I)=W+Z*SH12
              SY(I)=W*SH21+Z
              END DO
         GO TO 140
30 CONTINUE
         SH11=SPARAM(2)
         SH22=SPARAM(5)
              DO I=1,NSTEPS,INCX
              W=SX(I)
              Z=SY(I)
              SX(I)=W*SH11+Z
              SY(I)=-W+SH22*Z
              END DO
         GO TO 140
50 CONTINUE
         SH11=SPARAM(2)
         SH21=SPARAM(3)
         SH12=SPARAM(4)
         SH22=SPARAM(5)
              DO I=1,NSTEPS,INCX
              W=SX(I)
              Z=SY(I)
              SX(I)=W*SH11+Z*SH12
              SY(I)=W*SH21+Z*SH22
              END DO
         GO TO 140
70 CONTINUE
    KX=1
    KY=1
    IF(INCX .LT. 0) KX=1+(1-N)*INCX
    IF(INCY .LT. 0) KY=1+(1-N)*INCY
!
    IF(SFLAG)120,80,100
80 CONTINUE
    SH21=SPARAM(3)
    SH12=SPARAM(4)
         DO I=1,N
         W=SX(KX)
         Z=SY(KY)
         SX(KX)=W+Z*SH12
         SY(KY)=W*SH21+Z
         KX=KX+INCX
         KY=KY+INCY
         END DO
    GO TO 140
100 CONTINUE
    SH11=SPARAM(2)
    SH22=SPARAM(5)
         DO I=1,N
         W=SX(KX)
         Z=SY(KY)
         SX(KX)=W*SH11+Z
         SY(KY)=-W+SH22*Z
         KX=KX+INCX
         KY=KY+INCY
         END DO
    GO TO 140
120 CONTINUE
    SH11=SPARAM(2)
    SH21=SPARAM(3)
    SH12=SPARAM(4)
    SH22=SPARAM(5)
         DO I=1,N
         W=SX(KX)
         Z=SY(KY)
         SX(KX)=W*SH11+Z*SH12
         SY(KY)=W*SH21+Z*SH22
         KX=KX+INCX
         KY=KY+INCY
         END DO
140 CONTINUE
    RETURN
    END SUBROUTINE SROTM

SUBROUTINE DROTMG (DD1,DD2,DX1,DY1,DPARAM)
IMPLICIT NONE
!
!     CONSTRUCT THE MODIFIED GIVENS TRANSFORMATION MATRIX H WHICH ZEROS
!     THE SECOND COMPONENT OF THE 2-VECTOR  (DSQRT(DD1)*DX1,DSQRT(DD2)*
!     DY1)**T.
!     WITH DPARAM(1)=DFLAG, H HAS ONE OF THE FOLLOWING FORMS..
!
!     DFLAG=-1.D0     DFLAG=0.D0        DFLAG=1.D0     DFLAG=-2.D0
!
!       (DH11  DH12)    (1.D0  DH12)    (DH11  1.D0)    (1.D0  0.D0)
!     H=(          )    (          )    (          )    (          )
!       (DH21  DH22),   (DH21  1.D0),   (-1.D0 DH22),   (0.D0  1.D0).
!
!     LOCATIONS 2-4 OF DPARAM CONTAIN DH11,DH21,DH12, AND DH22
!     RESPECTIVELY. (VALUES OF 1.D0, -1.D0, OR 0.D0 IMPLIED BY THE
!     VALUE OF DPARAM(1) ARE NOT STORED IN DPARAM.)
!
!     IT IS ASSUMED THAT GAMSQ = GAM*GAM AND RGAMSQ = ONE/(GAM*GAM).
!     THE VALUES OF GAMSQ AND RGAMSQ SET IN THE DATA STATEMENT MAY BE
!     INEXACT.  THIS IS OK AS THEY ARE ONLY USED FOR TESTING THE SIZE
!     OF DD1 AND DD2.  ALL ACTUAL SCALING OF DATA IS DONE USING GAM.
!
DOUBLE PRECISION :: GAM, ONE, RGAMSQ
DOUBLE PRECISION, INTENT(INOUT) :: DD2
DOUBLE PRECISION :: DH11, DH21
DOUBLE PRECISION, INTENT(INOUT) :: DPARAM(5)
DOUBLE PRECISION :: DP2, DQ2, DU
DOUBLE PRECISION, INTENT(IN) :: DY1
DOUBLE PRECISION :: ZERO, GAMSQ
DOUBLE PRECISION, INTENT(INOUT) :: DD1
DOUBLE PRECISION :: DFLAG, DH12, DH22, DP1, DQ1, DTEMP
DOUBLE PRECISION, INTENT(INOUT) :: DX1
DOUBLE PRECISION :: TWO
!
DATA ZERO,ONE,TWO /0.D0,1.D0,2.D0/
DATA GAM,GAMSQ,RGAMSQ/4096.D0,16777216.D0,5.9604645D-8/
!
IF (DD1 .LT. ZERO) GO TO 60
DP2 = DD2*DY1
IF (DP2 .NE. ZERO) GO TO 20
    DFLAG = -TWO
    GO TO 260
!
!     REGULAR-CASE..
!
20 DP1 = DD1*DX1
DQ1 = DP1*DX1
DQ2 = DP2*DY1
!
IF (DABS(DQ1) .LE. DABS(DQ2)) GO TO 40
    DH21 = -DY1/DX1
    DH12 = DP2/DP1
!
    DU = ONE - DH12*DH21
    IF (DU .LE. ZERO) GO TO 60
!
         DFLAG = ZERO
         DH11 = ONE
         DH22 = ONE
         DD1 = DD1/DU
         DD2 = DD2/DU
         DX1 = DX1*DU
!         GO SCALE-CHECK..
         GO TO 100
!
40 CONTINUE
    IF (DD2 .LT. ZERO) GO TO 60
         DFLAG = ONE
         DH11 = DP1/DP2
         DH21 = -ONE
         DH12 = ONE
         DH22 = DX1/DY1
!
         DU = ONE + DH11*DH22
         DTEMP = DD2/DU
         DD2 = DD1/DU
         DD1 = DTEMP
         DX1 = DY1*DU
!         GO SCALE-CHECK
         GO TO 100
!
!     PROCEDURE..ZERO-H-D-AND-DX1..
!
60 CONTINUE
    DFLAG = -ONE
    DH11 = ZERO
    DH12 = ZERO
    DH21 = ZERO
    DH22 = ZERO
!
    DD1 = ZERO
    DD2 = ZERO
    DX1 = ZERO
    GO TO 250
!
!     PROCEDURE..SCALE-CHECK
!
100 CONTINUE
110 CONTINUE
    IF (DD1 .GT. RGAMSQ) GO TO 130
         IF (DD1 .EQ. ZERO) GO TO 160
         DFLAG = -ONE
         DD1 = DD1*(GAM*GAM)
         DX1 = DX1/GAM
         DH11 = DH11/GAM
         DH12 = DH12/GAM
    GO TO 110
!
130 CONTINUE
140 CONTINUE
    IF (DD1 .LT. GAMSQ) GO TO 160
         DFLAG = -ONE
         DD1 = DD1/(GAM*GAM)
         DX1 = DX1*GAM
         DH11 = DH11*GAM
         DH12 = DH12*GAM
    GO TO 140
!
160 CONTINUE
170 CONTINUE
    IF (DABS(DD2) .GT. RGAMSQ) GO TO 190
         IF (DD2 .EQ. ZERO) GO TO 220
         DFLAG = -ONE
         DD2 = DD2*(GAM*GAM)
         DH21 = DH21/GAM
         DH22 = DH22/GAM
    GO TO 170
!
190 CONTINUE
200 CONTINUE
    IF (DABS(DD2) .LT. GAMSQ) GO TO 220
         DFLAG = -ONE
         DD2 = DD2/(GAM*GAM)
         DH21 = DH21*GAM
         DH22 = DH22*GAM
    GO TO 200
!
220 CONTINUE
    IF(DFLAG)250,230,240
230 CONTINUE
         DPARAM(3)=DH21
         DPARAM(4)=DH12
         GO TO 260
240 CONTINUE
         DPARAM(2)=DH11
         DPARAM(5)=DH22
         GO TO 260
250 CONTINUE
         DPARAM(2)=DH11
         DPARAM(3)=DH21
         DPARAM(4)=DH12
         DPARAM(5)=DH22
260 CONTINUE
    DPARAM(1)=DFLAG
    RETURN
END SUBROUTINE DROTMG

SUBROUTINE DROTM (N,DX,INCX,DY,INCY,DPARAM)
IMPLICIT NONE
INTEGER, INTENT(IN) :: INCX, INCY, N
INTEGER :: I, KX, KY, NSTEPS
!
!     APPLY THE MODIFIED GIVENS TRANSFORMATION, H, TO THE 2 BY N MATRIX
!
!     (DX**T), WHERE **T INDICATES TRANSPOSE. THE ELEMENTS OF DX ARE IN
!     (DY**T)
!
!     DX(LX+I*INCX), I = 0 TO N-1, WHERE LX = 1 IF INCX .GE. 0, ELSE
!     LX = (-INCX)*N, AND SIMILARLY FOR SY USING LY AND INCY.
!
!     WITH DPARAM(1)=DFLAG, H HAS ONE OF THE FOLLOWING FORMS..
!
!     DFLAG=-1.D0     DFLAG=0.D0        DFLAG=1.D0     DFLAG=-2.D0
!
!       (DH11  DH12)    (1.D0  DH12)    (DH11  1.D0)    (1.D0  0.D0)
!     H=(          )    (          )    (          )    (          )
!       (DH21  DH22),   (DH21  1.D0),   (-1.D0 DH22),   (0.D0  1.D0).
!
DOUBLE PRECISION :: DFLAG, DH12, DH22
DOUBLE PRECISION, INTENT(INOUT) :: DX(*)
DOUBLE PRECISION :: TWO, Z, DH11, DH21, DPARAM(5)
DOUBLE PRECISION, INTENT(INOUT) :: DY(*)
DOUBLE PRECISION :: W, ZERO
!
DATA ZERO,TWO/0.D0,2.D0/
!
DFLAG=DPARAM(1)
IF(N .LE. 0 .OR.(DFLAG+TWO.EQ.ZERO)) GO TO 140
    IF(.NOT.(INCX.EQ.INCY.AND. INCX .GT.0)) GO TO 70
!
         NSTEPS=N*INCX
         IF(DFLAG) 50,10,30
10 CONTINUE
         DH21=DPARAM(3)
         DH12=DPARAM(4)
              DO I=1,NSTEPS,INCX
              W=DX(I)
              Z=DY(I)
              DX(I)=W+Z*DH12
              DY(I)=W*DH21+Z
              END DO
         GO TO 140
30 CONTINUE
         DH11=DPARAM(2)
         DH22=DPARAM(5)
              DO I=1,NSTEPS,INCX
              W=DX(I)
              Z=DY(I)
              DX(I)=W*DH11+Z
              DY(I)=-W+DH22*Z
              END DO
         GO TO 140
50 CONTINUE
         DH11=DPARAM(2)
         DH21=DPARAM(3)
         DH12=DPARAM(4)
         DH22=DPARAM(5)
              DO I=1,NSTEPS,INCX
              W=DX(I)
              Z=DY(I)
              DX(I)=W*DH11+Z*DH12
              DY(I)=W*DH21+Z*DH22
              END DO
         GO TO 140
70 CONTINUE
    KX=1
    KY=1
    IF(INCX .LT. 0) KX=1+(1-N)*INCX
    IF(INCY .LT. 0) KY=1+(1-N)*INCY
!
    IF(DFLAG)120,80,100
80 CONTINUE
    DH21=DPARAM(3)
    DH12=DPARAM(4)
         DO I=1,N
         W=DX(KX)
         Z=DY(KY)
         DX(KX)=W+Z*DH12
         DY(KY)=W*DH21+Z
         KX=KX+INCX
         KY=KY+INCY
         END DO
    GO TO 140
100 CONTINUE
    DH11=DPARAM(2)
    DH22=DPARAM(5)
         DO I=1,N
         W=DX(KX)
         Z=DY(KY)
         DX(KX)=W*DH11+Z
         DY(KY)=-W+DH22*Z
         KX=KX+INCX
         KY=KY+INCY
         END DO
    GO TO 140
120 CONTINUE
    DH11=DPARAM(2)
    DH21=DPARAM(3)
    DH12=DPARAM(4)
    DH22=DPARAM(5)
         DO I=1,N
         W=DX(KX)
         Z=DY(KY)
         DX(KX)=W*DH11+Z*DH12
         DY(KY)=W*DH21+Z*DH22
         KX=KX+INCX
         KY=KY+INCY
         END DO
140 CONTINUE
    RETURN
    END SUBROUTINE DROTM

REAL function SDOT(N,SX,INCX,SY,INCY)
IMPLICIT NONE
!
!     FORMS THE DOT PRODUCT OF TWO VECTORS.
!     USES UNROLLED LOOPS FOR INCREMENTS EQUAL TO ONE.
!     JACK DONGARRA, LINPACK, 3/11/78.
!
REAL, INTENT(IN) :: SX(*), SY(*)
REAL :: STEMP
INTEGER :: I
INTEGER, INTENT(IN) :: INCX, INCY
INTEGER :: IX, IY, M, MP1
INTEGER, INTENT(IN) :: N
!
STEMP = 0.0E0
SDOT = 0.0E0
IF(N.LE.0)RETURN
IF(INCX.EQ.1.AND.INCY.EQ.1)GO TO 20
!
!        CODE FOR UNEQUAL INCREMENTS OR EQUAL INCREMENTS
!          NOT EQUAL TO 1
!
IX = 1
IY = 1
IF(INCX.LT.0)IX = (-N+1)*INCX + 1
IF(INCY.LT.0)IY = (-N+1)*INCY + 1
DO I = 1,N
  STEMP = STEMP + SX(IX)*SY(IY)
  IX = IX + INCX
  IY = IY + INCY
END DO
SDOT = STEMP
RETURN
!
!        CODE FOR BOTH INCREMENTS EQUAL TO 1
!
!
!        CLEAN-UP LOOP
!
20 M = MOD(N,5)
IF( M .EQ. 0 ) GO TO 40
DO I = 1,M
  STEMP = STEMP + SX(I)*SY(I)
END DO
IF( N .LT. 5 ) GO TO 60
40 MP1 = M + 1
DO I = MP1,N,5
  STEMP = STEMP + SX(I)*SY(I) + SX(I + 1)*SY(I + 1) + &
&SX(I + 2)*SY(I + 2) + SX(I + 3)*SY(I + 3) + SX(I + 4)*SY(I + 4)
END DO
60 SDOT = STEMP
RETURN
END FUNCTION SDOT

