SUBROUTINE  SSCAL(N,SA,SX,INCX)
IMPLICIT NONE
!
!     SCALES A VECTOR BY A CONSTANT.
!     USES UNROLLED LOOPS FOR INCREMENT EQUAL TO 1.
!     JACK DONGARRA, LINPACK, 3/11/78.
!
REAL, INTENT(IN) :: SA
REAL, INTENT(INOUT) :: SX(*)
INTEGER :: I
INTEGER, INTENT(IN) :: INCX
INTEGER :: M, MP1
INTEGER, INTENT(IN) :: N
INTEGER :: NINCX
!
IF(N.LE.0)RETURN
IF(INCX.EQ.1)GO TO 20
!
!        CODE FOR INCREMENT NOT EQUAL TO 1
!
NINCX = N*INCX
DO I = 1,NINCX,INCX
  SX(I) = SA*SX(I)
END DO
RETURN
!
!        CODE FOR INCREMENT EQUAL TO 1
!
!
!        CLEAN-UP LOOP
!
20 M = MOD(N,5)
IF( M .EQ. 0 ) GO TO 40
DO I = 1,M
  SX(I) = SA*SX(I)
END DO
IF( N .LT. 5 ) RETURN
40 MP1 = M + 1
DO I = MP1,N,5
  SX(I) = SA*SX(I)
  SX(I + 1) = SA*SX(I + 1)
  SX(I + 2) = SA*SX(I + 2)
  SX(I + 3) = SA*SX(I + 3)
  SX(I + 4) = SA*SX(I + 4)
END DO
RETURN
END SUBROUTINE SSCAL

