DO I = 1,N
  CY(IY) = CY(IY) + CA*CX(IX)
  IX = IX + INCX
  IY = IY + INCY
END DO
RETURN
!
!        CODE FOR BOTH INCREMENTS EQUAL TO 1
!
20 DO I = 1,N
  CY(I) = CY(I) + CA*CX(I)
END DO
RETURN
END SUBROUTINE CAXPY

REAL function SASUM(N,SX,INCX)
IMPLICIT NONE
!
!     TAKES THE SUM OF THE ABSOLUTE VALUES.
!     USES UNROLLED LOOPS FOR INCREMENT EQUAL TO ONE.
!     JACK DONGARRA, LINPACK, 3/11/78.
!
REAL, INTENT(IN) :: SX(*)
REAL :: STEMP
INTEGER :: I
INTEGER, INTENT(IN) :: INCX
INTEGER :: M, MP1
INTEGER, INTENT(IN) :: N
INTEGER :: NINCX
!
SASUM = 0.0E0
STEMP = 0.0E0
IF(N.LE.0)RETURN
IF(INCX.EQ.1)GO TO 20
!
!        CODE FOR INCREMENT NOT EQUAL TO 1
!
NINCX = N*INCX
DO I = 1,NINCX,INCX
  STEMP = STEMP + ABS(SX(I))
END DO
SASUM = STEMP
RETURN
!
!        CODE FOR INCREMENT EQUAL TO 1
!
!
!        CLEAN-UP LOOP
!
20 M = MOD(N,6)
IF( M .EQ. 0 ) GO TO 40
DO I = 1,M
  STEMP = STEMP + ABS(SX(I))
END DO
IF( N .LT. 6 ) GO TO 60
40 MP1 = M + 1
DO I = MP1,N,6
  STEMP = STEMP + ABS(SX(I)) + ABS(SX(I + 1)) + ABS(SX(I + 2)) &
&+ ABS(SX(I + 3)) + ABS(SX(I + 4)) + ABS(SX(I + 5))
END DO
60 SASUM = STEMP
RETURN
END FUNCTION SASUM

double precision function DASUM(N,DX,INCX)
IMPLICIT NONE
!
!     TAKES THE SUM OF THE ABSOLUTE VALUES.
!     JACK DONGARRA, LINPACK, 3/11/78.
!
DOUBLE PRECISION, INTENT(IN) :: DX(*)
DOUBLE PRECISION :: DTEMP
INTEGER :: I
INTEGER, INTENT(IN) :: INCX
INTEGER :: M, MP1
INTEGER, INTENT(IN) :: N
INTEGER :: NINCX
!
DASUM = 0.0D0
DTEMP = 0.0D0
IF(N.LE.0)RETURN
IF(INCX.EQ.1)GO TO 20
!
!        CODE FOR INCREMENT NOT EQUAL TO 1
!
NINCX = N*INCX
DO I = 1,NINCX,INCX
  DTEMP = DTEMP + DABS(DX(I))
END DO
DASUM = DTEMP
RETURN
!
!        CODE FOR INCREMENT EQUAL TO 1
!
!
!        CLEAN-UP LOOP
!
20 M = MOD(N,6)
IF( M .EQ. 0 ) GO TO 40
DO I = 1,M
  DTEMP = DTEMP + DABS(DX(I))
END DO
IF( N .LT. 6 ) GO TO 60
40 MP1 = M + 1
DO I = MP1,N,6
  DTEMP = DTEMP + DABS(DX(I)) + DABS(DX(I + 1)) + DABS(DX(I + 2)) &
&+ DABS(DX(I + 3)) + DABS(DX(I + 4)) + DABS(DX(I + 5))
END DO
60 DASUM = DTEMP
RETURN
END FUNCTION DASUM

REAL function SCASUM(N,CX,INCX)
IMPLICIT NONE
!
!     TAKES THE SUM OF THE ABSOLUTE VALUES OF A COMPLEX VECTOR AND
!     RETURNS A SINGLE PRECISION RESULT.
!     JACK DONGARRA, LINPACK, 3/11/78.
!
COMPLEX, INTENT(IN) :: CX(*)
REAL :: STEMP
INTEGER :: I
INTEGER, INTENT(IN) :: INCX, N
INTEGER :: NINCX
!
SCASUM = 0.0E0
STEMP = 0.0E0
IF(N.LE.0)RETURN
IF(INCX.EQ.1)GO TO 20
!
!        CODE FOR INCREMENT NOT EQUAL TO 1
!
NINCX = N*INCX
DO I = 1,NINCX,INCX
  STEMP = STEMP + ABS(REAL(CX(I))) + ABS(AIMAG(CX(I)))
END DO
SCASUM = STEMP
RETURN
!
!        CODE FOR INCREMENT EQUAL TO 1
!
20 DO I = 1,N
  STEMP = STEMP + ABS(REAL(CX(I))) + ABS(AIMAG(CX(I)))
END DO
SCASUM = STEMP
RETURN
END FUNCTION SCASUM

REAL function SNRM2 ( N, SX, INCX)
IMPLICIT NONE
INTEGER, INTENT(IN) :: INCX, N
INTEGER :: I, J, NN
INTEGER :: NEXT
REAL, INTENT(IN) :: SX(*)
REAL :: CUTLO, CUTHI, HITEST, SUM, XMAX, ZERO, ONE
DATA   ZERO, ONE /0.0E0, 1.0E0/
!
!     EUCLIDEAN NORM OF THE N-VECTOR STORED IN SX() WITH STORAGE
!     INCREMENT INCX .
!     IF    N .LE. 0 RETURN WITH RESULT = 0.
!     IF N .GE. 1 THEN INCX MUST BE .GE. 1
!
!           C.L.LAWSON, 1978 JAN 08
!
!     FOUR PHASE METHOD     USING TWO BUILT-IN CONSTANTS THAT ARE
!     HOPEFULLY APPLICABLE TO ALL MACHINES.
!         CUTLO = MAXIMUM OF  SQRT(U/EPS)  OVER ALL KNOWN MACHINES.
!         CUTHI = MINIMUM OF  SQRT(V)      OVER ALL KNOWN MACHINES.
!     WHERE
!         EPS = SMALLEST NO. SUCH THAT EPS + 1. .GT. 1.
!         U   = SMALLEST POSITIVE NO.   (UNDERFLOW LIMIT)
!         V   = LARGEST  NO.            (OVERFLOW  LIMIT)
!
!     BRIEF OUTLINE OF ALGORITHM..
!
!     PHASE 1    SCANS ZERO COMPONENTS.
!     MOVE TO PHASE 2 WHEN A COMPONENT IS NONZERO AND .LE. CUTLO
!     MOVE TO PHASE 3 WHEN A COMPONENT IS .GT. CUTLO
!     MOVE TO PHASE 4 WHEN A COMPONENT IS .GE. CUTHI/M
!     WHERE M = N FOR X() REAL AND M = 2*N FOR COMPLEX.
!
!     VALUES FOR CUTLO AND CUTHI..
!     FROM THE ENVIRONMENTAL PARAMETERS LISTED IN THE IMSL CONVERTER
!     DOCUMENT THE LIMITING VALUES ARE AS FOLLOWS..
!     CUTLO, S.P.   U/EPS = 2**(-102) FOR  HONEYWELL.  CLOSE SECONDS ARE
!                   UNIVAC AND DEC AT 2**(-103)
!                   THUS CUTLO = 2**(-51) = 4.44089E-16
!     CUTHI, S.P.   V = 2**127 FOR UNIVAC, HONEYWELL, AND DEC.
!                   THUS CUTHI = 2**(63.5) = 1.30438E19
!     CUTLO, D.P.   U/EPS = 2**(-67) FOR HONEYWELL AND DEC.
!                   THUS CUTLO = 2**(-33.5) = 8.23181D-11
!     CUTHI, D.P.   SAME AS S.P.  CUTHI = 1.30438D19
!     DATA CUTLO, CUTHI / 8.232D-11,  1.304D19 /
!     DATA CUTLO, CUTHI / 4.441E-16,  1.304E19 /
DATA CUTLO, CUTHI / 4.441E-16,  1.304E19 /
!
IF(N .GT. 0) GO TO 10
   SNRM2  = ZERO
   GO TO 300
!
10 assign 30 to NEXT
SUM = ZERO
NN = N * INCX
!                                                 BEGIN MAIN LOOP
I = 1
20 GO TO NEXT,(30, 50, 70, 110)
30 IF( ABS(SX(I)) .GT. CUTLO) GO TO 85
assign 50 to NEXT
XMAX = ZERO
!
!                        PHASE 1.  SUM IS ZERO
!
50 IF( SX(I) .EQ. ZERO) GO TO 200
IF( ABS(SX(I)) .GT. CUTLO) GO TO 85
!
!                                PREPARE FOR PHASE 2.
assign 70 to NEXT
GO TO 105
!
!                                PREPARE FOR PHASE 4.
!
100 I = J
assign 110 to NEXT
SUM = (SUM / SX(I)) / SX(I)
105 XMAX = ABS(SX(I))
GO TO 115
!
!                   PHASE 2.  SUM IS SMALL.
!                             SCALE TO AVOID DESTRUCTIVE UNDERFLOW.
!
70 IF( ABS(SX(I)) .GT. CUTLO ) GO TO 75
!
!                     COMMON CODE FOR PHASES 2 AND 4.
!                     IN PHASE 4 SUM IS LARGE.  SCALE TO AVOID OVERFLOW.
!
110 IF( ABS(SX(I)) .LE. XMAX ) GO TO 115
   SUM = ONE + SUM * (XMAX / SX(I))**2
   XMAX = ABS(SX(I))
   GO TO 200
!
115 SUM = SUM + (SX(I)/XMAX)**2
GO TO 200
!
!
!                  PREPARE FOR PHASE 3.
!
75 SUM = (SUM * XMAX) * XMAX
!
!
!     FOR REAL OR D.P. SET HITEST = CUTHI/N
!     FOR COMPLEX      SET HITEST = CUTHI/(2*N)
!
85 HITEST = CUTHI/FLOAT( N )
!
!                   PHASE 3.  SUM IS MID-RANGE.  NO SCALING.
!
do 95 J = I,NN,INCX
IF(ABS(SX(J)) .GE. HITEST) GO TO 100
95 SUM = SUM + SX(J)**2
SNRM2 = SQRT( SUM )
GO TO 300
!
200 CONTINUE
I = I + INCX
IF ( I .LE. NN ) GO TO 20
!
!              END OF MAIN LOOP.
!
!              COMPUTE SQUARE ROOT AND ADJUST FOR SCALING.
!
SNRM2 = XMAX * SQRT(SUM)
300 CONTINUE
RETURN
END FUNCTION SNRM2

double precision function DNRM2 ( N, DX, INCX)
IMPLICIT NONE
INTEGER, INTENT(IN) :: INCX, N
INTEGER :: I, J, NN
INTEGER :: NEXT
DOUBLE PRECISION, INTENT(IN) :: DX(*)
DOUBLE PRECISION :: CUTLO, CUTHI, HITEST, SUM, XMAX, ZERO, ONE
DATA   ZERO, ONE /0.0D0, 1.0D0/
!
!     EUCLIDEAN NORM OF THE N-VECTOR STORED IN DX() WITH STORAGE
!     INCREMENT INCX .
!     IF    N .LE. 0 RETURN WITH RESULT = 0.
!     IF N .GE. 1 THEN INCX MUST BE .GE. 1
!
!           C.L.LAWSON, 1978 JAN 08
!
!     FOUR PHASE METHOD     USING TWO BUILT-IN CONSTANTS THAT ARE
!     HOPEFULLY APPLICABLE TO ALL MACHINES.
!         CUTLO = MAXIMUM OF  DSQRT(U/EPS)  OVER ALL KNOWN MACHINES.
!         CUTHI = MINIMUM OF  DSQRT(V)      OVER ALL KNOWN MACHINES.
!     WHERE
!         EPS = SMALLEST NO. SUCH THAT EPS + 1. .GT. 1.
!         U   = SMALLEST POSITIVE NO.   (UNDERFLOW LIMIT)
!         V   = LARGEST  NO.            (OVERFLOW  LIMIT)
!
!     BRIEF OUTLINE OF ALGORITHM..
!
!     PHASE 1    SCANS ZERO COMPONENTS.
!     MOVE TO PHASE 2 WHEN A COMPONENT IS NONZERO AND .LE. CUTLO
!     MOVE TO PHASE 3 WHEN A COMPONENT IS .GT. CUTLO
!     MOVE TO PHASE 4 WHEN A COMPONENT IS .GE. CUTHI/M
!     WHERE M = N FOR X() REAL AND M = 2*N FOR COMPLEX.
!
!     VALUES FOR CUTLO AND CUTHI..
!     FROM THE ENVIRONMENTAL PARAMETERS LISTED IN THE IMSL CONVERTER
!     DOCUMENT THE LIMITING VALUES ARE AS FOLLOWS..
!     CUTLO, S.P.   U/EPS = 2**(-102) FOR  HONEYWELL.  CLOSE SECONDS ARE
!                   UNIVAC AND DEC AT 2**(-103)
!                   THUS CUTLO = 2**(-51) = 4.44089E-16
!     CUTHI, S.P.   V = 2**127 FOR UNIVAC, HONEYWELL, AND DEC.
!                   THUS CUTHI = 2**(63.5) = 1.30438E19
!     CUTLO, D.P.   U/EPS = 2**(-67) FOR HONEYWELL AND DEC.
!                   THUS CUTLO = 2**(-33.5) = 8.23181D-11
!     CUTHI, D.P.   SAME AS S.P.  CUTHI = 1.30438D19
!     DATA CUTLO, CUTHI / 8.232D-11,  1.304D19 /
!     DATA CUTLO, CUTHI / 4.441E-16,  1.304E19 /
DATA CUTLO, CUTHI / 8.232D-11,  1.304D19 /
!
IF(N .GT. 0) GO TO 10
   DNRM2  = ZERO
   GO TO 300
!
10 assign 30 to NEXT
SUM = ZERO
NN = N * INCX
!                                                 BEGIN MAIN LOOP
I = 1
20 GO TO NEXT,(30, 50, 70, 110)
30 IF( DABS(DX(I)) .GT. CUTLO) GO TO 85
assign 50 to NEXT
XMAX = ZERO
!
!                        PHASE 1.  SUM IS ZERO
!
50 IF( DX(I) .EQ. ZERO) GO TO 200
IF( DABS(DX(I)) .GT. CUTLO) GO TO 85
!
!                                PREPARE FOR PHASE 2.
assign 70 to NEXT
GO TO 105
!
!                                PREPARE FOR PHASE 4.
!
100 I = J
assign 110 to NEXT
SUM = (SUM / DX(I)) / DX(I)
105 XMAX = DABS(DX(I))
GO TO 115
!
!                   PHASE 2.  SUM IS SMALL.
!                             SCALE TO AVOID DESTRUCTIVE UNDERFLOW.
!
70 IF( DABS(DX(I)) .GT. CUTLO ) GO TO 75
!
!                     COMMON CODE FOR PHASES 2 AND 4.
!                     IN PHASE 4 SUM IS LARGE.  SCALE TO AVOID OVERFLOW.
!
110 IF( DABS(DX(I)) .LE. XMAX ) GO TO 115
   SUM = ONE + SUM * (XMAX / DX(I))**2
   XMAX = DABS(DX(I))
   GO TO 200
!
115 SUM = SUM + (DX(I)/XMAX)**2
GO TO 200
!
!
!                  PREPARE FOR PHASE 3.
!
75 SUM = (SUM * XMAX) * XMAX
!
!
!     FOR REAL OR D.P. SET HITEST = CUTHI/N
!     FOR COMPLEX      SET HITEST = CUTHI/(2*N)
!
85 HITEST = CUTHI/FLOAT( N )
!
!                   PHASE 3.  SUM IS MID-RANGE.  NO SCALING.
!
do 95 J = I,NN,INCX
IF(DABS(DX(J)) .GE. HITEST) GO TO 100
95 SUM = SUM + DX(J)**2
DNRM2 = DSQRT( SUM )
GO TO 300
!
200 CONTINUE
I = I + INCX
IF ( I .LE. NN ) GO TO 20
!
!              END OF MAIN LOOP.
!
!              COMPUTE SQUARE ROOT AND ADJUST FOR SCALING.
!
DNRM2 = XMAX * DSQRT(SUM)
300 CONTINUE
RETURN
END FUNCTION DNRM2

REAL function SCNRM2( N, CX, INCX)
IMPLICIT NONE
INTEGER, INTENT(IN) :: INCX, N
INTEGER :: I, NN
LOGICAL :: IMAG, SCALE
INTEGER :: NEXT
REAL :: CUTLO, CUTHI, HITEST, SUM, XMAX, ABSX, ZERO, ONE
COMPLEX, INTENT(IN) :: CX(*)
DATA         ZERO, ONE /0.0E0, 1.0E0/
!
!     UNITARY NORM OF THE COMPLEX N-VECTOR STORED IN CX() WITH STORAGE
!     INCREMENT INCX .
!     IF    N .LE. 0 RETURN WITH RESULT = 0.
!     IF N .GE. 1 THEN INCX MUST BE .GE. 1
!
!           C.L.LAWSON , 1978 JAN 08
!
!     FOUR PHASE METHOD     USING TWO BUILT-IN CONSTANTS THAT ARE
!     HOPEFULLY APPLICABLE TO ALL MACHINES.
!         CUTLO = MAXIMUM OF  SQRT(U/EPS)  OVER ALL KNOWN MACHINES.
!         CUTHI = MINIMUM OF  SQRT(V)      OVER ALL KNOWN MACHINES.
!     WHERE
!         EPS = SMALLEST NO. SUCH THAT EPS + 1. .GT. 1.
!         U   = SMALLEST POSITIVE NO.   (UNDERFLOW LIMIT)
!         V   = LARGEST  NO.            (OVERFLOW  LIMIT)
!
!     BRIEF OUTLINE OF ALGORITHM..
!
!     PHASE 1    SCANS ZERO COMPONENTS.
!     MOVE TO PHASE 2 WHEN A COMPONENT IS NONZERO AND .LE. CUTLO
!     MOVE TO PHASE 3 WHEN A COMPONENT IS .GT. CUTLO
!     MOVE TO PHASE 4 WHEN A COMPONENT IS .GE. CUTHI/M
!     WHERE M = N FOR X() REAL AND M = 2*N FOR COMPLEX.
!
!     VALUES FOR CUTLO AND CUTHI..
!     FROM THE ENVIRONMENTAL PARAMETERS LISTED IN THE IMSL CONVERTER
!     DOCUMENT THE LIMITING VALUES ARE AS FOLLOWS..
!     CUTLO, S.P.   U/EPS = 2**(-102) FOR  HONEYWELL.  CLOSE SECONDS ARE
!                   UNIVAC AND DEC AT 2**(-103)
!                   THUS CUTLO = 2**(-51) = 4.44089E-16
!     CUTHI, S.P.   V = 2**127 FOR UNIVAC, HONEYWELL, AND DEC.
!                   THUS CUTHI = 2**(63.5) = 1.30438E19
!     CUTLO, D.P.   U/EPS = 2**(-67) FOR HONEYWELL AND DEC.
!                   THUS CUTLO = 2**(-33.5) = 8.23181D-11
!     CUTHI, D.P.   SAME AS S.P.  CUTHI = 1.30438D19
!     DATA CUTLO, CUTHI / 8.232D-11,  1.304D19 /
!     DATA CUTLO, CUTHI / 4.441E-16,  1.304E19 /
DATA CUTLO, CUTHI / 4.441E-16,  1.304E19 /
!
IF(N .GT. 0) GO TO 10
   SCNRM2  = ZERO
   GO TO 300
!
10 assign 30 to NEXT
SUM = ZERO
NN = N * INCX
!                                                 BEGIN MAIN LOOP
do 210 I = 1,NN,INCX
   ABSX = ABS(REAL(CX(I)))
   IMAG = .FALSE.
   GO TO NEXT,(30, 50, 70, 90, 110)
30 IF( ABSX .GT. CUTLO) GO TO 85
assign 50 to NEXT
SCALE = .FALSE.
!
!                        PHASE 1.  SUM IS ZERO
!
50 IF( ABSX .EQ. ZERO) GO TO 200
IF( ABSX .GT. CUTLO) GO TO 85
!
!                                PREPARE FOR PHASE 2.
assign 70 to NEXT
GO TO 105
!
!                                PREPARE FOR PHASE 4.
!
100 assign 110 to NEXT
SUM = (SUM / ABSX) / ABSX
105 SCALE = .TRUE.
XMAX = ABSX
GO TO 115
!
!                   PHASE 2.  SUM IS SMALL.
!                             SCALE TO AVOID DESTRUCTIVE UNDERFLOW.
!
70 IF( ABSX .GT. CUTLO ) GO TO 75
!
!                     COMMON CODE FOR PHASES 2 AND 4.
!                     IN PHASE 4 SUM IS LARGE.  SCALE TO AVOID OVERFLOW.
!
110 IF( ABSX .LE. XMAX ) GO TO 115
   SUM = ONE + SUM * (XMAX / ABSX)**2
   XMAX = ABSX
   GO TO 200
!
115 SUM = SUM + (ABSX/XMAX)**2
GO TO 200
!
!
!                  PREPARE FOR PHASE 3.
!
75 SUM = (SUM * XMAX) * XMAX
!
85 assign 90 to NEXT
SCALE = .FALSE.
!
!     FOR REAL OR D.P. SET HITEST = CUTHI/N
!     FOR COMPLEX      SET HITEST = CUTHI/(2*N)
!
HITEST = CUTHI/FLOAT( N )
HITEST = HITEST * 0.5
!
!                   PHASE 3.  SUM IS MID-RANGE.  NO SCALING.
!
90 IF(ABSX .GE. HITEST) GO TO 100
   SUM = SUM + ABSX**2
200 CONTINUE
!                  CONTROL SELECTION OF REAL AND IMAGINARY PARTS.
!
IF(IMAG) GO TO 210
   ABSX = ABS(AIMAG(CX(I)))
   IMAG = .TRUE.
GO TO NEXT,(  50, 70, 90, 110 )
!
210 CONTINUE
!
!              END OF MAIN LOOP.
!              COMPUTE SQUARE ROOT AND ADJUST FOR SCALING.
!
SCNRM2 = SQRT(SUM)
IF(SCALE) SCNRM2 = SCNRM2 * XMAX
300 CONTINUE
RETURN
END FUNCTION SCNRM2

INTEGER function ISAMAX(N,SX,INCX)
IMPLICIT NONE
!
!     FINDS THE INDEX OF ELEMENT HAVING MAX. ABSOLUTE VALUE.
!     JACK DONGARRA, LINPACK, 3/11/78.
!
REAL, INTENT(IN) :: SX(*)
REAL :: SMAX
INTEGER :: I
INTEGER, INTENT(IN) :: INCX
INTEGER :: IX
INTEGER, INTENT(IN) :: N
!
ISAMAX = 0
IF( N .LT. 1 ) RETURN
ISAMAX = 1
IF(N.EQ.1)RETURN
IF(INCX.EQ.1)GO TO 20
!
!        CODE FOR INCREMENT NOT EQUAL TO 1
!
IX = 1
SMAX = ABS(SX(1))
IX = IX + INCX
DO I = 2,N
   IF(ABS(SX(IX)).LE.SMAX) GO TO 5
   ISAMAX = I
   SMAX = ABS(SX(IX))
5 IX = IX + INCX
END DO
RETURN
!
!        CODE FOR INCREMENT EQUAL TO 1
!
20 SMAX = ABS(SX(1))
do 30 I = 2,N
   IF(ABS(SX(I)).LE.SMAX) GO TO 30
   ISAMAX = I
   SMAX = ABS(SX(I))
30 CONTINUE
RETURN
END FUNCTION ISAMAX

INTEGER function IDAMAX(N,DX,INCX)
IMPLICIT NONE
!
!     FINDS THE INDEX OF ELEMENT HAVING MAX. ABSOLUTE VALUE.
!     JACK DONGARRA, LINPACK, 3/11/78.
!
DOUBLE PRECISION, INTENT(IN) :: DX(*)
DOUBLE PRECISION :: DMAX
INTEGER :: I
INTEGER, INTENT(IN) :: INCX
INTEGER :: IX
INTEGER, INTENT(IN) :: N
!
IDAMAX = 0
IF( N .LT. 1 ) RETURN
IDAMAX = 1
IF(N.EQ.1)RETURN
IF(INCX.EQ.1)GO TO 20
!
!        CODE FOR INCREMENT NOT EQUAL TO 1
!
IX = 1
DMAX = DABS(DX(1))
IX = IX + INCX
DO I = 2,N
   IF(DABS(DX(IX)).LE.DMAX) GO TO 5
   IDAMAX = I
   DMAX = DABS(DX(IX))
5 IX = IX + INCX
END DO
RETURN
!
!        CODE FOR INCREMENT EQUAL TO 1
!
20 DMAX = DABS(DX(1))
do 30 I = 2,N
   IF(DABS(DX(I)).LE.DMAX) GO TO 30
   IDAMAX = I
   DMAX = DABS(DX(I))
30 CONTINUE
RETURN
END FUNCTION IDAMAX

INTEGER function ICAMAX(N,CX,INCX)
IMPLICIT NONE
!
!     FINDS THE INDEX OF ELEMENT HAVING MAX. ABSOLUTE VALUE.
!     JACK DONGARRA, LINPACK, 3/11/78.
!
COMPLEX :: CX(*)
REAL :: SMAX
INTEGER :: I
INTEGER, INTENT(IN) :: INCX
INTEGER :: IX
INTEGER, INTENT(IN) :: N
COMPLEX :: ZDUM
REAL :: CABS1
CABS1(ZDUM) = ABS(REAL(ZDUM)) + ABS(AIMAG(ZDUM))
!
ICAMAX = 0
IF( N .LT. 1 ) RETURN
ICAMAX = 1
IF(N.EQ.1)RETURN
IF(INCX.EQ.1)GO TO 20
!
!        CODE FOR INCREMENT NOT EQUAL TO 1
!
IX = 1
SMAX = CABS1(CX(1))
IX = IX + INCX
DO I = 2,N
   IF(CABS1(CX(IX)).LE.SMAX) GO TO 5
   ICAMAX = I
   SMAX = CABS1(CX(IX))
5 IX = IX + INCX
END DO
RETURN
!
!        CODE FOR INCREMENT EQUAL TO 1
!
20 SMAX = CABS1(CX(1))
do 30 I = 2,N
   IF(CABS1(CX(I)).LE.SMAX) GO TO 30
   ICAMAX = I
   SMAX = CABS1(CX(I))
30 CONTINUE
RETURN
END FUNCTION ICAMAX

SUBROUTINE MCVFS(A,KA,N,B)
IMPLICIT NONE
INTEGER, INTENT(IN) :: KA, N
INTEGER :: I, J, L
REAL, INTENT(IN) :: A(KA,N)
REAL, INTENT(INOUT) :: B(*)
!
L = 0
DO J = 1,N
   do 10 I = 1,J
   L = L + 1
10 B(L) = A(I,J)
END DO
RETURN
END SUBROUTINE MCVFS

SUBROUTINE DMCVFS(A,KA,N,B)
IMPLICIT NONE
INTEGER, INTENT(IN) :: KA, N
INTEGER :: I, J, L
DOUBLE PRECISION, INTENT(IN) :: A(KA,N)
DOUBLE PRECISION, INTENT(INOUT) :: B(*)
!
L = 0
DO J = 1,N
   do 10 I = 1,J
   L = L + 1
10 B(L) = A(I,J)
END DO
RETURN
END SUBROUTINE DMCVFS

SUBROUTINE MCVSF(A,KA,N,B)
IMPLICIT NONE
INTEGER, INTENT(IN) :: KA, N
INTEGER :: I, II, IM1, J, JJ, L
REAL, INTENT(INOUT) :: A(KA,N)
REAL, INTENT(IN) :: B(*)
!
A(1,1) = B(1)
IF (N .LT. 2) RETURN
L = (N*(N + 1))/2
!
J = N
do 11 JJ = 2,N
I = J
   do 10 II = 1,J
   A(I,J) = B(L)
   I = I - 1
10 L = L - 1
11 J = J - 1
!
DO I = 2,N
IM1 = I - 1
   do 20 J = 1,IM1
20 A(I,J) = A(J,I)
END DO
RETURN
END SUBROUTINE MCVSF

SUBROUTINE DMCVSF(A,KA,N,B)
IMPLICIT NONE
INTEGER, INTENT(IN) :: KA, N
INTEGER :: I, II, IM1, J, JJ, L
DOUBLE PRECISION, INTENT(INOUT) :: A(KA,N)
DOUBLE PRECISION, INTENT(IN) :: B(*)
!
A(1,1) = B(1)
IF (N .LT. 2) RETURN
L = (N*(N + 1))/2
!
J = N
do 11 JJ = 2,N
I = J
   do 10 II = 1,J
   A(I,J) = B(L)
   I = I - 1
10 L = L - 1
11 J = J - 1
!
DO I = 2,N
IM1 = I - 1
   do 20 J = 1,IM1
20 A(I,J) = A(J,I)
END DO
RETURN
END SUBROUTINE DMCVSF

SUBROUTINE MCVRD(M,N,A,KA,B,KB)
IMPLICIT NONE
INTEGER, INTENT(IN) :: KA, KB, M, N
INTEGER :: I, J
REAL, INTENT(IN) :: A(KA,N)
DOUBLE PRECISION, INTENT(INOUT) :: B(KB,N)
!
DO J = 1,N
   do 10 I = 1,M
10 B(I,J) = A(I,J)
END DO
RETURN
END SUBROUTINE MCVRD

SUBROUTINE MCVDR(M,N,A,KA,B,KB)
IMPLICIT NONE
INTEGER, INTENT(IN) :: KA, KB, M, N
INTEGER :: I, J
DOUBLE PRECISION, INTENT(IN) :: A(KA,N)
REAL, INTENT(INOUT) :: B(KB,N)
!
DO J = 1,N
   do 10 I = 1,M
10 B(I,J) = A(I,J)
END DO
RETURN
END SUBROUTINE MCVDR

SUBROUTINE MCVRC(M,N,A,KA,B,KB)
IMPLICIT NONE
INTEGER, INTENT(IN) :: KA, KB, M, N
INTEGER :: I, J
REAL, INTENT(IN) :: A(KA,N)
COMPLEX, INTENT(INOUT) :: B(KB,N)
!
DO J = 1,N
   do 10 I = 1,M
10 B(I,J) = CMPLX(A(I,J),0.0)
END DO
RETURN
END SUBROUTINE MCVRC

SUBROUTINE CMREAL(M,N,A,KA,B,KB)
IMPLICIT NONE
INTEGER, INTENT(IN) :: KA, KB, M, N
INTEGER :: I, J
COMPLEX, INTENT(IN) :: A(KA,N)
REAL, INTENT(INOUT) :: B(KB,N)
!
DO J = 1,N
   do 10 I = 1,M
10 B(I,J) = REAL(A(I,J))
END DO
RETURN
END SUBROUTINE CMREAL

SUBROUTINE CMIMAG(M,N,A,KA,B,KB)
IMPLICIT NONE
INTEGER, INTENT(IN) :: KA, KB, M, N
INTEGER :: I, J
COMPLEX, INTENT(IN) :: A(KA,N)
REAL, INTENT(INOUT) :: B(KB,N)
!
DO J = 1,N
   do 10 I = 1,M
10 B(I,J) = AIMAG(A(I,J))
END DO
RETURN
END SUBROUTINE CMIMAG

SUBROUTINE MCOPY(M,N,A,KA,B,KB)
IMPLICIT NONE
INTEGER, INTENT(IN) :: KA, KB, M, N
INTEGER :: I, J
REAL, INTENT(IN) :: A(KA,N)
REAL, INTENT(INOUT) :: B(KB,N)
!
DO J = 1,N
   do 10 I = 1,M
10 B(I,J) = A(I,J)
END DO
RETURN
END SUBROUTINE MCOPY

SUBROUTINE SMCOPY(N,A,B)
IMPLICIT NONE
INTEGER, INTENT(IN) :: N
INTEGER :: K, L
REAL, INTENT(IN) :: A(*)
REAL, INTENT(INOUT) :: B(*)
!
L = (N*(N + 1))/2
do 10 K = 1,L
10 B(K) = A(K)
RETURN
END SUBROUTINE SMCOPY

SUBROUTINE DMCOPY(M,N,A,KA,B,KB)
IMPLICIT NONE
INTEGER, INTENT(IN) :: KA, KB, M, N
